function validate([items, queries]) {
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  if (!Array.isArray(items) || items.length < 1 || items.length > 100000) return 'items needs 1 to 100000 entries.';
  if (items.some(item => !Array.isArray(item) || item.length !== 2)) return 'Each item is a [price, beauty] pair.';
  if (items.some(([price, beauty]) => !ok(price) || !ok(beauty))) return 'Prices and beauties are whole numbers from 1 to 10^9.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 values.';
  if (queries.some(v => !ok(v))) return 'Each query is a whole number from 1 to 10^9.';
  return null;
}

