function maximumBeauty(items, queries) {
  items.sort((a, b) => a[0] - b[0]);
  const order = queries.map((_, index) => index);
  order.sort((a, b) => queries[a] - queries[b]);
  const answer = new Array(queries.length).fill(0);
  let best = 0;
  let next = 0;
  for (const j of order) {
    while (next < items.length && items[next][0] <= queries[j]) {
      best = Math.max(best, items[next][1]);
      next++;
    }
    answer[j] = best;
  }
  return answer;
}

