function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const q = large ? 2000 : 1 + Math.floor(rand() * 8);
  const wide = rand() < 0.4;
  const top = wide ? 1000000000 : (large ? 3000 : 12);
  const pick = () => 1 + Math.floor(rand() * top);
  const items = [];
  for (let i = 0; i < n; i++) items.push([pick(), pick()]);
  const queries = [];
  for (let j = 0; j < q; j++) {
    // Mix random budgets with budgets that equal an existing price.
    queries.push(rand() < 0.3 ? items[Math.floor(rand() * n)][0] : pick());
  }
  return [items, queries];
}
